// Regenerates lib/supabase/database.types.ts from the local Supabase database.
// Requires `npm run db:start` first.
import { execFileSync } from "node:child_process";
import { writeFileSync } from "node:fs";

const types = execFileSync("npx", ["supabase", "gen", "types", "typescript", "--local"], { encoding: "utf8" });
writeFileSync(
  "lib/supabase/database.types.ts",
  "// Generated by `npm run db:types` (supabase gen types typescript --local). Do not edit by hand.\n" + types,
);
console.log("Wrote lib/supabase/database.types.ts");
